(()=>{
const K=window.KingdomSim,$=id=>document.getElementById(id);let chosen='britain',changed=false,api=null,mode='select';
const holder=document.createElement('section');holder.className='nation-picker';holder.innerHTML='<div class="eyebrow">选择你的国家</div><div id="nation-cards"></div><p id="nation-detail"></p><label class="opponent-choice">对手国家 <select id="opponent-nation"><option value="auto">自动选择其他国家</option>'+Object.values(K.nations).map(n=>'<option value="'+n.id+'">'+n.name+'</option>').join('')+'</select></label>';
document.querySelector('.intro-sub').after(holder);document.querySelector('.steps').innerHTML='<div class="feature-pills"><span>海陆作战</span><span>国家专属兵种</span><span>四类资源</span></div>';
for(const n of Object.values(K.nations)){const b=document.createElement('button');b.className='nation-card';b.dataset.nation=n.id;b.innerHTML='<span class="national-emblem">'+n.flag+'</span><strong>'+n.name+'</strong><small>'+n.short+'</small>';b.onclick=()=>{chosen=n.id;changed=true;render();$('start').innerHTML='以'+n.name+'开启新战役 <span>→</span>'};$('nation-cards').append(b)}
function render(){for(const b of $('nation-cards').children){const active=b.dataset.nation===chosen;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}const n=K.nations[chosen];$('nation-detail').innerHTML='<b>'+n.bonus+'</b><br><span>取舍：'+n.tradeoff+'</span><br>'+n.description}
$('opponent-nation').onchange=()=>{changed=true;$('start').innerHTML='开启新的海岸远征 <span>→</span>'};$('difficulty').addEventListener('change',()=>{changed=true;$('start').innerHTML='按新设置开始战役 <span>→</span>'});render();
const install=document.createElement('button');install.className='install-app secondary';install.textContent='安装到手机 / 电脑';$('start').after(install);const offline=document.createElement('p');offline.id='offline-status';offline.textContent='可安装为独立窗口 App';install.after(offline);
const stone=document.createElement('span');stone.title='石料';stone.innerHTML='<i>⬢</i><b id="stone">0</b><small>石料</small>';document.querySelector('.resources').insertBefore(stone,document.querySelector('.resources').lastElementChild);
const nationHud=document.createElement('div');nationHud.id='nation-hud';document.querySelector('.campaign').append(nationHud);
const fleet=document.createElement('button');fleet.id='select-fleet';fleet.innerHTML='⚓ <span>选择舰队</span><kbd>V</kbd>';$('select-army').after(fleet);fleet.onclick=()=>api?.fleet();
const navyTab=document.createElement('button');navyTab.dataset.tab='naval';navyTab.textContent='海军';$('build-tabs').append(navyTab);
const sheet=document.createElement('button');sheet.id='sheet-toggle';sheet.setAttribute('aria-label','展开或收起命令面板');sheet.innerHTML='⌄';document.querySelector('.selection').append(sheet);sheet.onclick=()=>{document.body.classList.toggle('commands-collapsed');sheet.textContent=document.body.classList.contains('commands-collapsed')?'⌃':'⌄';api?.resize()};
const touch=document.createElement('div');touch.id='touch-toolbar';touch.innerHTML='<button data-mode="select" class="active">⌖<span>点选</span></button><button data-mode="box">▱<span>框选</span></button><button data-mode="pan">✥<span>移图</span></button>';
document.querySelector('.battlefield').append(touch);for(const b of touch.children)b.onclick=()=>{mode=b.dataset.mode;for(const x of touch.children)x.classList.toggle('active',x===b);api?.toast(mode==='box'?'拖出选框选择部队':mode==='pan'?'拖动地图，双指可缩放':'点选单位，再点目标指挥；长按选同类')};
const quick=document.createElement('button');quick.id='quick-retreat';quick.innerHTML='↶<span>撤退</span>';quick.onclick=()=>api?.retreat();touch.append(quick);
const confirm=document.createElement('div');confirm.id='placement-confirm';confirm.hidden=true;confirm.innerHTML='<button id="confirm-build">✓ 确认建造</button><button id="cancel-build">取消</button>';document.querySelector('.battlefield').append(confirm);$('confirm-build').onclick=()=>api?.confirmBuild();$('cancel-build').onclick=()=>api?.cancelBuild();
const change=document.createElement('button');change.id='change-nation';change.className='secondary';change.textContent='选择国家 · 新战役';$('new-game').after(change);change.onclick=()=>api?.newWar();const pauseInstall=document.createElement('button');pauseInstall.className='install-app secondary';pauseInstall.textContent='安装 App / 离线状态';change.after(pauseInstall);
$('welcome').addEventListener('cancel',e=>e.preventDefault());
window.NavalUI={bind(value){api=value},get mode(){return mode},get changed(){return changed},isMobile:()=>matchMedia('(pointer:coarse)').matches||innerWidth<700,nations:()=>[chosen,$('opponent-nation').value==='auto'?Object.keys(K.nations).find(k=>k!==chosen):$('opponent-nation').value],restore(state){chosen=state.nations[0];$('opponent-nation').value=state.nations[1];changed=false;render()},selection(e){if(!this.isMobile())return;const compact=e&&!K.defs[e.kind]?.building&&e.kind!=='villager';document.body.classList.toggle('commands-collapsed',!!compact);sheet.textContent=compact?'⌃':'⌄';api?.resize()},placed(value){confirm.hidden=!value},clearChanged(){changed=false}};
})();
